{
  "predictors": [
    {
      "name": "Employee Satisfaction Score",
      "construction": "Use textual analysis on annual reports and company news to construct a sentiment score related to employee satisfaction over the past year.",
      "rationale": "Companies with more satisfied employees may have higher productivity and lower turnover, leading to better performance.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Product Recall Frequency",
      "construction": "Count the number of product recalls reported by a company in the last five years using company press releases and regulatory filings.",
      "rationale": "Frequent product recalls may indicate operational inefficiencies or quality control issues.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Customer Churn Rate",
      "construction": "Estimate churn rate using subscription and service cancellation data from company filings over the past year.",
      "rationale": "Lower churn rates suggest strong customer loyalty and stable revenue streams.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Patents Filed Growth Rate",
      "construction": "Calculate the annual growth rate of the number of patents filed by the company over the last three years.",
      "rationale": "An increasing number of patents may indicate strong innovation and future growth potential.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Board Diversity Index",
      "construction": "Create an index based on gender, ethnicity, and age diversity of board members as reported in proxy statements.",
      "rationale": "Greater diversity on corporate boards may lead to better decision-making and corporate governance.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Environmental Violation Count",
      "construction": "Count the number of environmental violations reported against the company in the last five years.",
      "rationale": "Frequent violations may indicate poor environmental management and potential for reputational damage.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "CEO Media Presence",
      "construction": "Measure the frequency of CEO mentions in major financial news outlets over the past year.",
      "rationale": "Higher media presence of a CEO might indicate aggressive promotion strategies and leadership visibility.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Supply Chain Disruption Count",
      "construction": "Count reported supply chain disruptions in company press releases and industry news over the past two years.",
      "rationale": "Fewer disruptions suggest robust supply chain management and operational efficiency.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Cybersecurity Incident Frequency",
      "construction": "Count the number of reported cybersecurity incidents affecting the company over the past three years.",
      "rationale": "Frequent incidents may indicate vulnerabilities and potential financial and reputational losses.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Innovation Sentiment Score",
      "construction": "Use textual analysis on earnings calls and company reports to derive sentiment related to innovation over the past year.",
      "rationale": "Positive sentiment regarding innovation could signal future growth and competitive advantage.",
      "higher_returns_for": "high values of the measure"
    }
  ]
}
